// Gold trophy cup for the YOU WON / cashout celebration (BetResultNotifications).
// Stored as a base64 data URI in a .ts module because GitHub snapshot pushes
// carry text files only, so the binary PNG (src/assets/result-trophy-clear.png)
// can never reach the repo and Vercel git builds failed with ENOENT on it.
// Source image: 768x987 RGBA, resized to 512x658 (max display size) with PIL LANCZOS.
// To regenerate: resize src/assets/result-trophy-clear.png to 512w, base64 it, paste below.
const TROPHY_DATA_URI =
  "data:image/png;base64,";

export default TROPHY_DATA_URI;
